/*
 * vec-fp2.S - vfrec7 and vfrsqrt7 against Spike, every entry of both
 * 7-bit estimate tables: 128 inputs a run whose top fraction bits are the
 * index -- for vfrsqrt7 shifted one further, so that the index's top bit
 * is the exponent's parity -- at several exponents, both signs; results
 * that come out subnormal; subnormal inputs, those too small for a
 * finite reciprocal under each rounding mode and sign; and the special
 * values. The tables are rv_fpu.c's, regenerated by
 * test_vfp_estimate_tables from a rule; this asks the oracle.
 *
 * probe-march: rv32imafdc_zicsr_zve32f
 * probe-models: spike
 * probe-spike-isa: rv32imafdc_zicsr_zve32f_zvl128b
 * probe-regs: s1 s2 s3 s4 s5 s6 s7 a1
 *
 *   s1  vfrec7, exponent 127: every entry
 *   s2  vfrec7, negative, exponents 1 and 200
 *   s3  vfrec7, exponents 253 and 254: subnormal results
 *   s4  vfrec7, subnormal inputs, under rne, rtz, rdn, rup, rmm, both
 *       signs: overflow to infinity or the largest finite value
 *   s5  vfrsqrt7, exponents 126/127 and 200/201: every entry
 *   s6  vfrsqrt7, subnormal inputs, and negative ones (NaN, NV)
 *   s7  both on the special values, fflags after each
 *   a1  set once every case has run
 */
    .option norvc
    .section .text.init
    .globl rvtest_entry_point
rvtest_entry_point:
    li   t0, (1 << 13) | (1 << 9)  /* FS and VS Initial */
    csrs mstatus, t0
    li   s1, 0
    li   s2, 0
    li   s3, 0
    li   s4, 0
    li   s5, 0
    li   s6, 0
    li   s7, 0
    li   a1, 0
    csrw fflags, zero
    csrwi frm, 0

/*
 * acc = (rotl(acc, 5) ^ x) * an odd constant. Without the multiply the
 * fold is linear over XOR: a constant error in every element of a run
 * cancels -- over 32 words whenever it flips an even number of bits, over
 * 128 always -- and vec-fp2.S's s1 and s2 folded equal from different
 * results.
 */
.macro MIX acc, x
    slli t3, \acc, 5
    srli \acc, \acc, 27
    or   \acc, \acc, t3
    xor  \acc, \acc, \x
    li   t3, 0x9E3779B1          /* not linear: see the note above */
    mul  \acc, \acc, t3
.endm

.macro FOLDBUF acc, n
    la   t5, vbuf
    li   t6, \n
1:  lw   t4, 0(t5)
    MIX  \acc, t4
    addi t5, t5, 4
    addi t6, t6, -1
    bnez t6, 1b
.endm

.macro FOLDV8 acc, v
    la   t5, vbuf
    vs8r.v \v, (t5)
    FOLDBUF \acc, 32
.endm

.macro FFL acc
    csrr t1, fflags
    MIX  \acc, t1
    csrw fflags, zero
.endm

/*
 * op on the 128 words base | (j << sh) | low, j from 0 to 127, folded
 * into acc a group of 32 at a time, then fflags.
 */
.macro EST op, acc, base, sh, low
    la   a0, ebuf
    li   t0, 0
    li   t2, 128
    li   a2, \base | \low
1:  slli t1, t0, \sh
    or   t1, t1, a2
    sw   t1, 0(a0)
    addi a0, a0, 4
    addi t0, t0, 1
    bne  t0, t2, 1b
    la   a0, ebuf
    li   t2, 4
2:  li   t0, 32
    vsetvli zero, t0, e32, m8, ta, ma
    vle32.v v8, (a0)
    \op v16, v8
    FOLDV8 \acc, v16
    addi a0, a0, 128
    addi t2, t2, -1
    bnez t2, 2b
    FFL  \acc
.endm

/* --- s1-s3: vfrec7 on normals ----------------------------------------- */
    EST vfrec7.v, s1, 0x3F800000, 16, 0x5A5
    EST vfrec7.v, s1, 0x3F800000, 16, 0xFFFF
    EST vfrec7.v, s2, 0x80800000, 16, 0x1
    EST vfrec7.v, s2, 0xE4000000, 16, 0x8000
    EST vfrec7.v, s3, 0x7E800000, 16, 0x1234
    EST vfrec7.v, s3, 0xFF000000, 16, 0xFFFF

/* --- s4: vfrec7 on subnormals, each rounding mode and sign ------------- */
.macro SUBREC acc
    EST vfrec7.v, \acc, 0x00000000, 16, 0x0
    EST vfrec7.v, \acc, 0x80000000, 16, 0x7
    EST vfrec7.v, \acc, 0x00000000, 10, 0x1
.endm
    csrwi frm, 0
    SUBREC s4
    csrwi frm, 1
    SUBREC s4
    csrwi frm, 2
    SUBREC s4
    csrwi frm, 3
    SUBREC s4
    csrwi frm, 4
    SUBREC s4
    csrwi frm, 0

/* --- s5: vfrsqrt7 on normals: j's top bit is the exponent's low one ---- */
    EST vfrsqrt7.v, s5, 0x3F000000, 17, 0x5A5
    EST vfrsqrt7.v, s5, 0x3F000000, 17, 0x1FFFF
    EST vfrsqrt7.v, s5, 0x64000000, 17, 0x1
    EST vfrsqrt7.v, s5, 0x01000000, 17, 0x10000

/* --- s6: vfrsqrt7 on subnormals and negatives -------------------------- */
    EST vfrsqrt7.v, s6, 0x00000000, 16, 0x0
    EST vfrsqrt7.v, s6, 0x00000000, 15, 0x3
    EST vfrsqrt7.v, s6, 0x00000000, 9, 0x1
    EST vfrsqrt7.v, s6, 0xBF800000, 16, 0x0
    EST vfrsqrt7.v, s6, 0x80000000, 16, 0x1

/* --- s7: the special values -------------------------------------------- */
    li   t0, 16
    vsetvli zero, t0, e32, m4, ta, ma
    la   a0, specials
    vle32.v v8, (a0)
    vfrec7.v v16, v8
    vs4r.v v16, (a0)
    la   t5, specials
    li   t6, 16
3:  lw   t4, 0(t5)
    MIX  s7, t4
    addi t5, t5, 4
    addi t6, t6, -1
    bnez t6, 3b
    FFL  s7
    la   a0, specials2
    vle32.v v8, (a0)
    vfrsqrt7.v v16, v8
    vs4r.v v16, (a0)
    la   t5, specials2
    li   t6, 16
4:  lw   t4, 0(t5)
    MIX  s7, t4
    addi t5, t5, 4
    addi t6, t6, -1
    bnez t6, 4b
    FFL  s7

    li   a1, 1
    la   t0, tohost
    li   t1, 1
    sw   t1, 0(t0)
5:  j    5b

    .data
    .align 6
    .globl tohost
tohost: .quad 0
    .globl fromhost
fromhost: .quad 0
    .align 4
specials:
    .word 0x00000000, 0x80000000, 0x7F800000, 0xFF800000
    .word 0x7FC00000, 0x7F800001, 0xFFC00001, 0x7F7FFFFF
    .word 0x00800000, 0x80800000, 0x00400000, 0x00200000
    .word 0x001FFFFF, 0x80000001, 0x7E800000, 0x7F000000
specials2:
    .word 0x00000000, 0x80000000, 0x7F800000, 0xFF800000
    .word 0x7FC00000, 0x7F800001, 0xFFC00001, 0x7F7FFFFF
    .word 0x00800000, 0x80800000, 0x00000001, 0x007FFFFF
    .word 0x3F800000, 0x40800000, 0xBF800000, 0x00000002
ebuf:
    .space 512
vbuf:
    .space 512
